  public function executeUpdate()
  {
    if (!$this->getRequestParameter('vinculada_id'))
    {
      $vinculada = new Vinculada();
      $vinculada->setFechaCreacion(date('Y-m-d G:i:s'));
      $old_files = false;
      $txt_oldfiles = "";
      $opcion = 0;
    }
    else
    {
      $opcion = 1;	
      $vinculada = VinculadaPeer::retrieveByPk($this->getRequestParameter('vinculada_id'));
      $old_files = true;
      $txt_oldfiles = $vinculada->getRuta();
      $this->forward404Unless($vinculada);
    }
    //****************************************************************************************
	$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $vinculada->setDescripcion($this->getRequestParameter('descripcion'));        
    $vinculada->setFolios($this->getRequestParameter('folios'));
    $vinculada->setUsuarioId($usuario_conectado);
    //****************************************************************************************
    $str_files = trim($this->getRequestParameter('ruta'));
    $vinculada->setRuta($this->resolveUrlAttachment($str_files,$old_files,$txt_oldfiles));
    //****************************************************************************************
    $vinculada->save();
    //****************************************************************************************
    // TRANSFERENCIA DE VINCULADA
    if (!$this->getRequestParameter('transferencia_id'))
    {
      $transferencia = new Transferencia();
    }
    else
    {
      $transferencia = TransferenciaPeer::retrieveByPk($this->getRequestParameter('transferencia_id'));
      $this->forward404Unless($transferencia);
    }
    //****************************************************************************************
    $transferencia->setVinculadaId($vinculada->getVinculadaId());
    $transferencia->setOrigentransferenciaid(4);
    $transferencia->setDestinotransferenciaId(2);
    $transferencia->setUnidaddocumentalId($this->getRequestParameter('unidad_documental'));
    $transferencia->setTipodocumentalId($this->getRequestParameter('tipo_documental'));
	$transferencia->setFechaCreacion(date('Y-m-d G:i:s'));  
	$transferencia->setEstadotransferenciaId(1);
	$transferencia->save();
	//****************************************************************************************
	$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	$user_transfer = new UsuarioTransferencia();
	$user_transfer->setUsuariotransferenciaId();
	$user_transfer->setRolusuariotransferenciaId(1);
	$user_transfer->setTransferenciaId($transferencia->getTransferenciaId());
	$user_transfer->setUsuarioId($usuario_conectado);
	$user_transfer->save();
	//****************************************************************************************	
    return $this->redirect($this->getRequest()->getScriptName().'/vinculada/show?vinculada_id='.$vinculada->getVinculadaId().'&opcion='.$opcion);
  }

